      "module_name": "Mathlib.Algebra.Group.Hom.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} {N : Type u_5} [inst : Add M] [inst_1 : Add N] (f : M →ₙ+ N) (a b : M), f (a + b) = f a + f b"
    },
    {
      "name": "AddHom.map_add'",
      "module_name": "Mathlib.Algebra.Group.Hom.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_10} {N : Type u_11} [inst : Add M] [inst_1 : Add N] (self : M →ₙ+ N) (x y : M),\n  self.toFun (x + y) = self.toFun x + self.toFun y"
    },
    {
      "name": "AddMonoidHom.map_dfinsuppSumAddHom",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {β : ι → Type v} [inst : DecidableEq ι] {R : Type u_1} {S : Type u_2} [inst_1 : AddCommMonoid R]\n  [inst_2 : AddCommMonoid S] [inst_3 : (i : ι) → AddZeroClass (β i)] (h : R →+ S) (f : Π₀ (i : ι), β i)\n  (g : (i : ι) → β i →+ R), h ((DFinsupp.sumAddHom g) f) = (DFinsupp.sumAddHom fun i => h.comp (g i)) f"
    },
    {
      "name": "map_add",
      "module_name": "Mathlib.Algebra.Group.Hom.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} {N : Type u_5} {F : Type u_9} [inst : Add M] [inst_1 : Add N] [inst_2 : FunLike F M N]\n  [AddHomClass F M N] (f : F) (x y : M), f (x + y) = f x + f y"
    },
    {
      "name": "AddMonoidHom.map_add",
      "module_name": "Mathlib.Algebra.Group.Hom.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} {N : Type u_5} [inst : AddZero M] [inst_1 : AddZero N] (f : M →+ N) (a b : M), f (a + b) = f a + f b"
    }
  ]
}
